import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
  /** Drawn before the label. With `iconsOnly`, the label stays available to assistive tech. */
  icon?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  /** Hides each label visually and keeps it in the accessible name. */
  iconsOnly?: boolean
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  iconsOnly = false,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.icon}
                  {iconsOnly ? <span className="sr-only">{option.label}</span> : option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

"use client"

/**
 * Optimistic stage overlay. The host still derives the stage with `getStage`.
 * A rejected `onMoveCandidate` drops the overlay so the card returns.
 */

import * as React from "react"

import type { AtsCandidate, AtsGetStage } from "@/lib/ats"

export type OptimisticMoveResult = { ok: true } | { ok: false; reason: "blocked" | "rejected" }

export function useOptimisticStage<TMeta>(
  candidates: readonly AtsCandidate<TMeta>[],
  getStage: AtsGetStage<TMeta>,
  options?: {
    canMove?: (from: string, to: string) => boolean
    onMoveCandidate?: (id: string, from: string, to: string) => void | Promise<void>
  },
) {
  const [pending, setPending] = React.useState<Record<string, string>>({})
  const tickets = React.useRef<Record<string, number>>({})
  const canMove = options?.canMove
  const onMoveCandidate = options?.onMoveCandidate

  const resolve = React.useCallback(
    (candidate: AtsCandidate<TMeta>) => pending[candidate.id] ?? getStage(candidate),
    [getStage, pending],
  )

  const caughtUp = Object.entries(pending).filter(([id, to]) => {
    const candidate = candidates.find((item) => item.id === id)
    return Boolean(candidate && getStage(candidate) === to)
  })
  if (caughtUp.length > 0) {
    const next = { ...pending }
    for (const [id] of caughtUp) delete next[id]
    setPending(next)
  }

  const move = React.useCallback(
    async (id: string, from: string, to: string): Promise<OptimisticMoveResult> => {
      if (from === to) return { ok: true }
      if (canMove && !canMove(from, to)) return { ok: false, reason: "blocked" }
      if (!onMoveCandidate) return { ok: false, reason: "blocked" }
      const ticket = (tickets.current[id] ?? 0) + 1
      tickets.current[id] = ticket
      setPending((current) => ({ ...current, [id]: to }))
      try {
        await onMoveCandidate(id, from, to)
        return { ok: true }
      } catch {
        if (tickets.current[id] === ticket) {
          setPending((current) => {
            if (!(id in current)) return current
            const next = { ...current }
            delete next[id]
            return next
          })
        }
        return { ok: false, reason: "rejected" }
      }
    },
    [canMove, onMoveCandidate],
  )

  return { resolve, move, pending }
}

export const RANGE_OPTIONS = [
  { key: "today", label: "Today" },
  { key: "7d", label: "Last 7 days" },
  { key: "30d", label: "Last 30 days" },
  { key: "90d", label: "Last 90 days" },
  { key: "12m", label: "Last 12 months" },
] as const

export type RangeKey = (typeof RANGE_OPTIONS)[number]["key"]

export type ResolvedRange = {
  key: RangeKey
  label: string
  from: number
  to: number
  prevFrom: number
  prevTo: number
  bucket: "hour" | "day" | "month"
}

const DAY = 86_400_000

export function isRangeKey(value: string): value is RangeKey {
  return RANGE_OPTIONS.some((option) => option.key === value)
}

/** Offset of `timeZone` at `ts`, in ms. UTC is 0. */
export function timeZoneOffsetMs(timeZone: string, ts: number): number {
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(new Date(ts))
  const parts = Object.fromEntries(formatted.map((part) => [part.type, part.value]))
  const asUtc = Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour) % 24,
    Number(parts.minute),
    Number(parts.second),
  )
  return asUtc - ts
}

/** Move a zoned midnight by whole calendar days, including 23h and 25h DST days. */
export function addZonedDays(dayStart: number, days: number, timeZone = "UTC"): number {
  return startOfZonedDay(dayStart + days * DAY + 12 * 3_600_000, timeZone)
}

export function startOfZonedDay(ts: number, timeZone = "UTC"): number {
  const offset = timeZoneOffsetMs(timeZone, ts)
  const local = ts + offset
  const midnightLocal = Math.floor(local / DAY) * DAY
  const guess = midnightLocal - timeZoneOffsetMs(timeZone, midnightLocal - offset)
  const check = timeZoneOffsetMs(timeZone, guess)
  return midnightLocal - check
}

export function resolveRange(
  key: RangeKey,
  now = Date.now(),
  timeZone = "UTC",
): ResolvedRange {
  const option = RANGE_OPTIONS.find((item) => item.key === key) ?? RANGE_OPTIONS[1]
  const today = startOfZonedDay(now, timeZone)
  let from = today
  let bucket: ResolvedRange["bucket"] = "day"
  let span = DAY

  if (key === "today") {
    from = today
    bucket = "hour"
    span = addZonedDays(today, 1, timeZone) - today
  } else if (key === "12m") {
    const offset = timeZoneOffsetMs(timeZone, today)
    const local = new Date(today + offset)
    const start = Date.UTC(local.getUTCFullYear(), local.getUTCMonth() - 11, 1)
    from = start - timeZoneOffsetMs(timeZone, start - offset)
    bucket = "month"
    span = now - from
  } else {
    const days = key === "7d" ? 7 : key === "30d" ? 30 : 90
    from = addZonedDays(today, -(days - 1), timeZone)
    span = addZonedDays(today, 1, timeZone) - from
    bucket = "day"
  }

  return {
    key: option.key,
    label: option.label,
    from,
    to: now,
    prevFrom: from - span,
    prevTo: now - span,
    bucket,
  }
}

/** Inclusive window. */
export function inRange(ts: number, from: number, to: number): boolean {
  return ts >= from && ts <= to
}

export function filterByRange<T>(
  rows: readonly T[],
  getTime: (row: T) => number | null,
  from: number,
  to: number,
): T[] {
  return rows.filter((row) => {
    const ts = getTime(row)
    return ts != null && inRange(ts, from, to)
  })
}

export type DatePreset = {
  key: string
  label: string
}

export const CALL_PRESETS: DatePreset[] = [
  { key: "any", label: "Any time" },
  { key: "today", label: "Today" },
  { key: "tomorrow", label: "Tomorrow" },
  { key: "next7", label: "Next 7 days" },
  { key: "next30", label: "Next 30 days" },
  { key: "last7", label: "Last 7 days" },
  { key: "last30", label: "Last 30 days" },
]

/** `[from, to)` for a named preset, or null when the preset does not filter. */
export function presetBounds(
  preset: string,
  now = Date.now(),
  timeZone = "UTC",
): [number, number] | null {
  const today = startOfZonedDay(now, timeZone)
  switch (preset) {
    case "today":
      return [today, addZonedDays(today, 1, timeZone)]
    case "tomorrow":
      return [addZonedDays(today, 1, timeZone), addZonedDays(today, 2, timeZone)]
    case "next7":
      return [now, now + 7 * DAY]
    case "next30":
      return [now, now + 30 * DAY]
    case "last7":
      return [now - 7 * DAY, now]
    case "last30":
      return [now - 30 * DAY, now]
    case "last90":
      return [now - 90 * DAY, now]
    default:
      return null
  }
}

